CREATE TABLE IF NOT EXISTS user_industries (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  user_id BIGINT NOT NULL,
  industry_id VARCHAR(128) NOT NULL,
  industry_name VARCHAR(128) NOT NULL,
  source_type VARCHAR(32) NOT NULL DEFAULT 'PRESET',
  status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uk_user_industries (user_id, industry_id),
  INDEX idx_user_industries_user (user_id)
);

UPDATE users SET industry_id = 'catering' WHERE industry_id IS NULL OR industry_id IN ('default-industry', 'general');

ON DUPLICATE KEY UPDATE question_text = VALUES(question_text), category = VALUES(category), top_level_score = VALUES(top_level_score), status = 'ENABLED';

SELECT u.id, 'catering', '餐饮', 'PRESET' FROM users u WHERE NOT EXISTS (SELECT 1 FROM user_industries x WHERE x.user_id = u.id AND x.industry_id = 'catering');
